//! The published PNX conformance vectors, through `re pnx verify`.
//!
//! `tests/vectors/pnx/conformance/` is a verbatim copy of
//! `tacet/conformance/vectors/v1/pnx_00{2,3,4,5}_*.json` from the Crovia
//! repository (croviatrust.com/registry/tacet/spec/vectors/v1/). They are
//! generated by the Python reference `tacet-pnx` from a deterministic
//! scenario and checked there by a Python and a JavaScript runner. This
//! file is the third runner: every expectation the other two check, the
//! Rust verifier must reproduce — verdicts per asset, the overall verdict,
//! the exit code, the seal binding, and the error a fault produces.
//!
//! The vectors are data, not code: copy new ones over, do not edit them.

use std::{
    fs,
    path::Path,
    process::{Command, Output},
};

use serde_json::Value;

fn re(dir: &Path, args: &[String]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_re"))
        .args(args)
        .current_dir(dir)
        .env("NO_COLOR", "1")
        .output()
        .unwrap()
}

fn vector(name: &str) -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors/pnx/conformance")
        .join(name);
    serde_json::from_slice(&fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display())))
        .unwrap()
}

fn report(out: &Output) -> Value {
    serde_json::from_slice(&out.stdout).unwrap_or_else(|e| {
        panic!(
            "{e}: no JSON report\n{}\n{}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        )
    })
}

/// Write `assets_hex` (label → hex bytes) into `dir` and return the
/// `--asset LABEL=PATH` arguments naming them.
fn asset_args(dir: &Path, assets_hex: &Value) -> Vec<String> {
    let mut args = Vec::new();
    for (label, hex) in assets_hex.as_object().unwrap() {
        let path = dir.join(format!("{label}.asset"));
        fs::write(&path, hex::decode(hex.as_str().unwrap()).unwrap()).unwrap();
        args.push("--asset".into());
        args.push(format!("{label}={}", path.display()));
    }
    args
}

fn verify(dir: &Path, document: &Value, assets_hex: Option<&Value>) -> (i32, Value) {
    let path = dir.join("proof.json");
    fs::write(&path, serde_json::to_vec(document).unwrap()).unwrap();
    let mut args = vec![
        "pnx".to_string(),
        "verify".into(),
        path.display().to_string(),
    ];
    if let Some(a) = assets_hex {
        args.extend(asset_args(dir, a));
    }
    args.push("--json".into());
    let out = re(dir, &args);
    (out.status.code().unwrap_or(-1), report(&out))
}

fn exit_for(ok: bool, verdict: &str) -> i32 {
    match (ok, verdict) {
        (false, _) => 2,
        (true, "absent") => 0,
        (true, _) => 1,
    }
}

fn errors_joined(rep: &Value) -> String {
    let mut all: Vec<&str> = rep["errors"]
        .as_array()
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    if let Some(s) = rep.get("seal_errors").and_then(Value::as_array) {
        all.extend(s.iter().filter_map(Value::as_str));
    }
    all.join(" | ")
}

